/**
 * The Python SDK's batches, judged by the relay's own code.
 *
 * `provian-python-sdk/tests/fixtures/python_device_requests.json` holds the exact batch POST
 * the Python PE recorder (`provian.meter.PeRecorder`) sends for two recorded PEs — headers,
 * raw body bytes — and the PEs the Python store holds behind it (regenerated by
 * `tests/fixtures/generate_relay_fixture.py`; the Python suite pins that the fixture still
 * matches what the recorder sends). Here the
 * relay's wire checks (`validateBatchShape`, `batchHashOf`, `verifyActChain`, `actRecordOf`,
 * `peHashOf`, `canonicalJson`), its body binding (`deviceBodyBinding`, the route's own check)
 * and its sealed-box opener judge those bytes. Each check has a RED control.
 */
import { describe, expect, it } from '@jest/globals';
import fs from 'fs';
import path from 'path';
import type { Request } from 'express';
import { deviceBodyBinding } from '../../routes/meter';
import {
  METER_GENESIS_PREV_HASH,
  actRecordOf,
  batchHashOf,
  canonicalJson,
  peHashOf,
  validateBatchShape,
  verifyActChain,
  type PeBatch,
  type PeV2,
} from './meter-wire';
import { fromB64u, openWithKey } from './sealed-box';

interface CapturedRequest {
  readonly capture: string;
  readonly method: string;
  readonly path: string;
  readonly headers: Record<string, string>;
  readonly body_utf8: string;
  readonly pes: PeV2[];
}

const FIXTURE = JSON.parse(fs.readFileSync(
  path.resolve(__dirname, '../../../../provian-python-sdk/tests/fixtures/python_device_requests.json'), 'utf8',
)) as { seal_recipient_secret_b64u: string; requests: CapturedRequest[] };

function asRequest(headers: Record<string, string>, rawBody: string): Request {
  const lower: Record<string, string> = {};
  for (const [k, v] of Object.entries(headers)) lower[k.toLowerCase()] = v;
  return { headers: lower, rawBody, deviceAuthMethod: 'bearer' } as unknown as Request;
}

describe('Python SDK batches — the relay judges the bytes Python sends', () => {
  it('the fixture population is the recorder\'s one batch, of more than one act', () => {
    expect(FIXTURE.requests.map((r) => r.capture)).toEqual(['recorder']);
    for (const r of FIXTURE.requests) {
      expect(r.pes.length).toBeGreaterThan(1);
      expect((JSON.parse(r.body_utf8) as PeBatch).acts.length).toBe(r.pes.length);
    }
  });

  for (const r of FIXTURE.requests) {
    describe(r.capture, () => {
      const batch = JSON.parse(r.body_utf8) as PeBatch;

      it('goes to POST /v1/meter/batch, body-bound under the device key', () => {
        expect(`${r.method} ${r.path}`).toBe('POST /v1/meter/batch');
        expect(r.headers.Authorization.startsWith('DeviceKey ')).toBe(true);
        expect(deviceBodyBinding(asRequest(r.headers, r.body_utf8))).toEqual({ bound: true, signatureAuthenticated: false });
      });

      it('RED: one changed byte, or no HMAC header, is not body-bound', () => {
        const tampered = r.body_utf8.replace('"seq":1', '"seq":2');
        expect(tampered).not.toBe(r.body_utf8);
        expect(deviceBodyBinding(asRequest(r.headers, tampered))).toBeNull();
        const { 'X-Provian-Body-HMAC': _hmac, ...unbound } = r.headers;
        expect(deviceBodyBinding(asRequest(unbound, r.body_utf8))).toEqual({ bound: false, signatureAuthenticated: false });
      });

      it('is the relay\'s canonical JSON, passes its shape check and continues from genesis', () => {
        expect(canonicalJson(batch)).toBe(r.body_utf8);
        expect(validateBatchShape(batch)).toEqual({ ok: true, batch });
        expect(batch.prev_batch_hash).toBe(METER_GENESIS_PREV_HASH);
        expect(verifyActChain(METER_GENESIS_PREV_HASH, batch.acts)).toEqual({ ok: true });
        expect(batchHashOf(batch)).toMatch(/^[0-9a-f]{64}$/);
      });

      it('carries exactly the act record of each PE the Python store holds (pe_hash recomputed here)', () => {
        for (const pe of r.pes) expect(peHashOf(pe)).toBe(pe.pe_hash);
        expect(batch.acts).toEqual(r.pes.map((pe) => actRecordOf(pe)));
        expect(r.body_utf8).not.toContain('"description"');
      });

      it('RED: an act edited after hashing fails the relay\'s shape check; a forged PE hash differs', () => {
        const edited = JSON.parse(r.body_utf8) as PeBatch;
        const act = edited.acts[0] as unknown as { pricing: { metadata: Record<string, unknown> } };
        act.pricing.metadata.network_calls = 99;
        expect(validateBatchShape(edited)).toEqual({ ok: false, error: 'acts_root_mismatch' });
        expect(peHashOf({ ...r.pes[0], action_type: 'agent_action' })).not.toBe(r.pes[0].pe_hash);
      });

      it('each sealed copy opens, under the recipient key, to the exact stored PE', () => {
        const secret = fromB64u(FIXTURE.seal_recipient_secret_b64u);
        const sealed = batch.sealed ?? [];
        expect(sealed.map((s) => s.to)).toEqual(r.pes.map(() => 'linked_human'));
        expect(sealed.map((s) => JSON.parse(openWithKey(secret, fromB64u(s.box)).toString('utf8')))).toEqual(r.pes);
        // RED: the wrong key never opens it.
        expect(() => openWithKey(Buffer.alloc(32, 7), fromB64u(sealed[0].box))).toThrow();
      });
    });
  }
});
